import "core-js/modules/esnext.iterator.constructor.js";
import "core-js/modules/esnext.iterator.filter.js";
import "core-js/modules/esnext.iterator.find.js";
import "core-js/modules/esnext.iterator.map.js";
import { ref, onMounted, computed } from "vue";
import { db } from "@/firebase";
import { collection, getDocs, doc, updateDoc, getDoc, Timestamp } from "firebase/firestore";
export default {
  setup() {
    const requests = ref([]);
    const isViewing = ref(false);
    const viewRequestData = ref({});
    const searchQuery = ref("");
    const statusFilter = ref("all");
    const fetchRequests = async () => {
      try {
        const querySnapshot = await getDocs(collection(db, "purchaseRequests"));
        requests.value = querySnapshot.docs.map(doc => {
          const data = doc.data();
          return {
            id: doc.id,
            ...data,
            // Ensure we have default values for required fields
            itemName: data.itemName || "Unnamed Item",
            quantity: data.quantity || 0,
            description: data.description || "No description provided",
            status: data.status || "Pending",
            // Convert Firestore timestamps to JS Date objects
            createdAt: data.createdAt instanceof Timestamp ? data.createdAt.toDate() : new Date(data.createdAt || Date.now()),
            updatedAt: data.updatedAt instanceof Timestamp ? data.updatedAt.toDate() : new Date(data.updatedAt || Date.now()),
            approvalDate: data.approvalDate instanceof Timestamp ? data.approvalDate.toDate() : data.approvalDate ? new Date(data.approvalDate) : null,
            requiredDate: data.requiredDate instanceof Timestamp ? data.requiredDate.toDate() : data.requiredDate ? new Date(data.requiredDate) : null
          };
        });
        console.log("Fetched requests:", JSON.stringify(requests.value, null, 2)); // Improved logging
      } catch (error) {
        console.error("Error fetching purchase requests:", error);
        alert("Failed to fetch purchase requests. Please try again.");
      }
    };
    const filteredRequests = computed(() => {
      return requests.value.filter(request => {
        // Apply search filter
        if (searchQuery.value) {
          const query = searchQuery.value.toLowerCase();
          return (request.itemName?.toLowerCase() || "").includes(query) || (request.description?.toLowerCase() || "").includes(query);
        }
        return true;
      }).filter(request => {
        // Apply status filter
        if (statusFilter.value !== "all") {
          return (request.status?.toLowerCase() || "").includes(statusFilter.value);
        }
        return true;
      });
    });

    // Fixed viewRequest function to directly fetch the request by ID
    const viewRequest = async requestId => {
      try {
        console.log(`Viewing request with ID: ${requestId}`);

        // Find the request in our local array first
        const localRequest = requests.value.find(req => req.id === requestId);
        if (localRequest) {
          // Use the local data
          viewRequestData.value = {
            ...localRequest
          };
          isViewing.value = true;
          console.log("Viewing request data:", JSON.stringify(viewRequestData.value, null, 2)); // Improved logging
        } else {
          // If not found locally, fetch from Firestore
          const requestDoc = await getDoc(doc(db, "purchaseRequests", requestId));
          if (requestDoc.exists()) {
            const data = requestDoc.data();
            viewRequestData.value = {
              id: requestId,
              ...data,
              // Ensure we have default values and proper date conversions
              itemName: data.itemName || "Unnamed Item",
              quantity: data.quantity || 0,
              description: data.description || "No description provided",
              status: data.status || "Pending",
              createdAt: data.createdAt instanceof Timestamp ? data.createdAt.toDate() : new Date(data.createdAt || Date.now()),
              updatedAt: data.updatedAt instanceof Timestamp ? data.updatedAt.toDate() : new Date(data.updatedAt || Date.now()),
              approvalDate: data.approvalDate instanceof Timestamp ? data.approvalDate.toDate() : data.approvalDate ? new Date(data.approvalDate) : null,
              requiredDate: data.requiredDate instanceof Timestamp ? data.requiredDate.toDate() : data.requiredDate ? new Date(data.requiredDate) : null
            };
            isViewing.value = true;
            console.log("Fetched and viewing request data:", JSON.stringify(viewRequestData.value, null, 2)); // Improved logging
          } else {
            console.error("Request not found");
            alert("Request not found");
          }
        }
      } catch (error) {
        console.error("Error viewing request:", error);
        alert("Failed to load request details");
      }
    };
    const approveRequest = async requestId => {
      try {
        const requestRef = doc(db, "purchaseRequests", requestId);
        const approvalDate = new Date().toISOString();
        await updateDoc(requestRef, {
          status: "Approved",
          approvalDate
        });

        // Update the local state
        const request = requests.value.find(req => req.id === requestId);
        if (request) {
          request.status = "Approved";
          request.approvalDate = approvalDate;
        }

        // Update modal if open
        if (isViewing.value && viewRequestData.value.id === requestId) {
          viewRequestData.value.status = "Approved";
          viewRequestData.value.approvalDate = approvalDate;
        }

        // Show success notification
        showNotification("Purchase request approved successfully!");
      } catch (error) {
        console.error("Error approving purchase request:", error);
        alert("Failed to approve the purchase request.");
      }
    };
    const rejectRequest = async requestId => {
      try {
        const requestRef = doc(db, "purchaseRequests", requestId);
        const rejectionDate = new Date().toISOString();
        await updateDoc(requestRef, {
          status: "Rejected",
          rejectionDate
        });

        // Update the local state
        const request = requests.value.find(req => req.id === requestId);
        if (request) {
          request.status = "Rejected";
          request.rejectionDate = rejectionDate;
        }

        // Update modal if open
        if (isViewing.value && viewRequestData.value.id === requestId) {
          viewRequestData.value.status = "Rejected";
          viewRequestData.value.rejectionDate = rejectionDate;
        }

        // Show success notification
        showNotification("Purchase request rejected.");
      } catch (error) {
        console.error("Error rejecting purchase request:", error);
        alert("Failed to reject the purchase request.");
      }
    };
    const closeModal = () => {
      isViewing.value = false;
      viewRequestData.value = {};
    };
    const formatDate = dateString => {
      if (!dateString) return "N/A";
      try {
        const date = dateString instanceof Date ? dateString : new Date(dateString);
        if (isNaN(date.getTime())) {
          return "Invalid Date";
        }
        return date.toLocaleDateString('en-US', {
          year: 'numeric',
          month: 'short',
          day: 'numeric',
          hour: '2-digit',
          minute: '2-digit'
        });
      } catch (error) {
        console.error("Error formatting date:", error);
        return "Date Error";
      }
    };
    const showNotification = message => {
      // Simple notification implementation
      const notification = document.createElement("div");
      notification.className = "notification";
      notification.textContent = message;
      document.body.appendChild(notification);
      setTimeout(() => {
        notification.classList.add("show");
      }, 10);
      setTimeout(() => {
        notification.classList.remove("show");
        setTimeout(() => {
          document.body.removeChild(notification);
        }, 300);
      }, 3000);
    };
    onMounted(fetchRequests);
    return {
      requests,
      filteredRequests,
      isViewing,
      viewRequestData,
      searchQuery,
      statusFilter,
      viewRequest,
      approveRequest,
      rejectRequest,
      formatDate,
      closeModal
    };
  }
};
